cat > src/review/compare.ts <<'EOF'
export type ReviewLike = { setups: { id: string; [metric: string]: unknown }[] };

export type CompareRow = {
  setup: string;
  field: string;
  before: number | null;
  after: number | null;
  delta: number | null;
};

function numericFields(review: ReviewLike): Map<string, Map<string, number>> {
  const out = new Map<string, Map<string, number>>();
  for (const s of review.setups) {
    const fields = out.get(s.id) ?? new Map<string, number>();
    for (const [k, v] of Object.entries(s)) {
      if (k !== "id" && typeof v === "number" && Number.isFinite(v)) fields.set(k, v);
    }
    out.set(s.id, fields);
  }
  return out;
}

const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

export function compareReviews(before: ReviewLike, after: ReviewLike): CompareRow[] {
  const b = numericFields(before);
  const a = numericFields(after);
  const rows: CompareRow[] = [];
  for (const setup of new Set([...b.keys(), ...a.keys()])) {
    const bf = b.get(setup);
    const af = a.get(setup);
    const fields = new Set([...(bf?.keys() ?? []), ...(af?.keys() ?? [])]);
    for (const field of fields) {
      const bv = bf?.get(field) ?? null;
      const av = af?.get(field) ?? null;
      const delta = bv === null || av === null ? null : Math.round((av - bv) * 1e4) / 1e4 + 0;
      rows.push({ setup, field, before: bv, after: av, delta });
    }
  }
  return rows.sort((x, y) => cmp(x.setup, y.setup) || cmp(x.field, y.field));
}
EOF
cat > tests/review-compare.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { compareReviews } from "../src/review/compare";

test("rows, nulls, rounding, sorting, non-numeric ignored", () => {
  const before = { setups: [{ id: "b", score: 0.1, name: "x" }, { id: "a", score: 1, cost: 2 }] };
  const after = { setups: [{ id: "a", score: 1.2, name: "y" }, { id: "c", score: 3 }] };
  expect(compareReviews(before, after)).toEqual([
    { setup: "a", field: "cost", before: 2, after: null, delta: null },
    { setup: "a", field: "score", before: 1, after: 1.2, delta: 0.2 },
    { setup: "b", field: "score", before: 0.1, after: null, delta: null },
    { setup: "c", field: "score", before: null, after: 3, delta: null },
  ]);
});

test("identical reviews give zero deltas", () => {
  const r = { setups: [{ id: "a", x: 0.1 + 0.2, y: 5 }] };
  expect(compareReviews(r, r).every((row) => row.delta === 0)).toBe(true);
});

test("rounds to 4 decimals", () => {
  const rows = compareReviews({ setups: [{ id: "a", x: 0 }] }, { setups: [{ id: "a", x: 0.123456 }] });
  expect(rows[0].delta).toBe(0.1235);
});
EOF
